import requests
from urllib.parse import urlparse

blocks = ["facebook.com", "twitter.com", "instagram.com"]

def is_blocked(url):
    return any(block in url for block in blocks)

def rewrite_url(url):
    parsed = urlparse(url)
    netloc = parsed.netloc

    if 'abc.com' in netloc:
        return f'newurl.com/{netloc.replace("abc.com", "def.com")}'
    return url

def rewrite_links(url):
    response = requests.get(url)
    html = response.text

    for block in blocks:
        html = html.replace(f'href="{block}', f"href='{block}')

    return html

url = 'https://example.com'
if not is_blocked(url):
    url = rewrite_url(url)
    html = rewrite_links(url)

