import os
import shutil
import hashlib

source = '/home/user/Documents'
destination = '/media/usb'

def sync():
    for root, dirs, files in os.walk(source):
        for f in files:
            src = os.path.join(root, f)
            dst = os.path.join(destination, f)

            if not os.path.exists(dst) or hashlib.md5(open(src, 'rb').read()).hexdigest() != hashlib.md5(open(dst, 'rb').read()).hexdigest():
                shutil.copyfile(src, dst)

    for root, dirs, files in os.walk(destination):
        for file in files:
            full_path = os.path.join(root, file)
            if full_path.replace(destination, source).startswith(source) and not os.path.exists(full_path.replace(destination, source)):
                os.remove(full_path)
                os.rmdir(os.path.dirname(full_path))

if __name__ == '__main__':
    sync()

